import { index, integer, primaryKey, sqliteTable, text, uniqueIndex } from 'drizzle-orm/sqlite-core'

// Ids are text (UUIDs generated by the repositories). Timestamps are ISO strings.
// JSON columns hold JSON text; the repositories parse and serialize them.

export const workspaces = sqliteTable('workspaces', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  repoPath: text('repo_path').notNull(),
  baseBranch: text('base_branch').notNull(),
  slug: text('slug').notNull(),
  /** Push the branch and open a pull request when a ticket reaches Review. */
  openPrOnReview: integer('open_pr_on_review', { mode: 'boolean' }).notNull().default(false),
  createdAt: text('created_at').notNull()
})

/** A workspace's lineups: the roles that work a ticket in turn, ordered by position. */
export const lineupRoles = sqliteTable(
  'lineup_roles',
  {
    id: text('id').primaryKey(),
    workspaceId: text('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    lineup: text('lineup').notNull(),
    position: integer('position').notNull(),
    name: text('name').notNull(),
    instructions: text('instructions').notNull(),
    activePhase: text('active_phase').notNull(),
    onProblem: text('on_problem').notNull(),
    /** The id of an earlier role in the same lineup; null hands back to the previous role. */
    handBackTo: text('hand_back_to'),
    model: text('model'),
    effort: text('effort'),
    toolProfile: text('tool_profile').notNull()
  },
  (t) => [uniqueIndex('lineup_roles_position_uq').on(t.workspaceId, t.lineup, t.position)]
)

export const tickets = sqliteTable(
  'tickets',
  {
    id: text('id').primaryKey(),
    workspaceId: text('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    number: integer('number').notNull(),
    kind: text('kind').notNull(),
    title: text('title').notNull(),
    intent: text('intent').notNull(), // JSON: IntentEntry[]
    spec: text('spec').notNull(),
    labels: text('labels').notNull(), // JSON: string[]
    manualColumn: text('manual_column').notNull(),
    branch: text('branch'),
    worktreePath: text('worktree_path'),
    prUrl: text('pr_url'),
    prNumber: integer('pr_number'),
    /** Why the last push or pull request failed; null once one succeeds. */
    prError: text('pr_error'),
    createdAt: text('created_at').notNull(),
    updatedAt: text('updated_at').notNull()
  },
  (t) => [uniqueIndex('tickets_workspace_number_uq').on(t.workspaceId, t.number)]
)

export const criteria = sqliteTable(
  'criteria',
  {
    ticketId: text('ticket_id')
      .notNull()
      .references(() => tickets.id, { onDelete: 'cascade' }),
    position: integer('position').notNull(),
    text: text('text').notNull(),
    checked: integer('checked', { mode: 'boolean' }).notNull().default(false)
  },
  (t) => [primaryKey({ columns: [t.ticketId, t.position] })]
)

export const agentRuns = sqliteTable(
  'agent_runs',
  {
    id: text('id').primaryKey(),
    ticketId: text('ticket_id')
      .notNull()
      .references(() => tickets.id, { onDelete: 'cascade' }),
    role: text('role').notNull(),
    sessionId: text('session_id'),
    model: text('model'),
    effort: text('effort'),
    startedAt: text('started_at').notNull(),
    endedAt: text('ended_at'),
    endReason: text('end_reason', { enum: ['handoff', 'stopped', 'failed'] })
  },
  (t) => [index('agent_runs_ticket_idx').on(t.ticketId)]
)

export const agentEvents = sqliteTable(
  'agent_events',
  {
    runId: text('run_id')
      .notNull()
      .references(() => agentRuns.id, { onDelete: 'cascade' }),
    seq: integer('seq').notNull(),
    at: text('at').notNull(),
    json: text('json').notNull()
  },
  (t) => [primaryKey({ columns: [t.runId, t.seq] })]
)

export const decisions = sqliteTable(
  'decisions',
  {
    id: text('id').primaryKey(),
    ticketId: text('ticket_id')
      .notNull()
      .references(() => tickets.id, { onDelete: 'cascade' }),
    agentRunId: text('agent_run_id')
      .notNull()
      .references(() => agentRuns.id, { onDelete: 'cascade' }),
    kind: text('kind').notNull(),
    question: text('question').notNull(),
    options: text('options').notNull(), // JSON: string[]
    recommended: integer('recommended'),
    status: text('status').notNull(),
    answer: text('answer'), // JSON: DecisionAnswer | null
    allowAlways: integer('allow_always', { mode: 'boolean' }).notNull().default(true),
    createdAt: text('created_at').notNull(),
    answeredAt: text('answered_at')
  },
  (t) => [index('decisions_ticket_idx').on(t.ticketId)]
)

export const allowRules = sqliteTable(
  'allow_rules',
  {
    id: text('id').primaryKey(),
    workspaceId: text('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    toolName: text('tool_name').notNull(),
    pattern: text('pattern')
  },
  (t) => [index('allow_rules_workspace_idx').on(t.workspaceId)]
)

// Worktrees that still need removing; deliberately no foreign key, so a row can outlive its ticket.
export const pendingCleanups = sqliteTable('pending_cleanups', {
  ticketId: text('ticket_id').primaryKey(),
  repoPath: text('repo_path').notNull(),
  worktreePath: text('worktree_path').notNull(),
  branch: text('branch').notNull(),
  createdAt: text('created_at').notNull()
})
